type Symbol = u32;                                   // interned identifier
struct Resolver { scopes: Vec<HashMap<Symbol, Def>>, global: HashMap<Symbol, Def> }
impl Resolver {
    fn define(&mut self, name: Symbol, def: Def) -> bool {
        self.scopes.last_mut().unwrap().insert(name, def).is_none()   // dup -> false
    }
    fn lookup(&self, name: Symbol) -> Option<&Def> {                   // inner -> outer
        self.scopes.iter().rev().find_map(|frame| frame.get(&name))
            .or_else(|| self.global.get(&name))
    }
}

