struct Resolver { ribs: IndexVec<RibId, Rib>, scopes: IndexVec<ScopeId, ScopeData> }
struct Rib { namespace: Namespace, bindings: Vec<(Symbol, DefId)>, parent: Option<RibId> }
fn resolve(&self, from: RibId, ns: Namespace, name: Symbol) -> Option<DefId> {
    std::iter::successors(Some(from), |r| self.ribs[*r].parent)
        .filter(|r| self.ribs[*r].namespace == ns)
        .find_map(|r| self.ribs[r].bindings.iter().rev()
            .find(|(n, _)| *n == name).map(|(_, d)| *d))
}
